<?php $page_title='Add User';require_once __DIR__.'/../includes/header.php';if(!is_admin())die('Admin only');if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO users(name,email,password,role,status) VALUES(?,?,?,?,?)")->execute([$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role'],'active']);header('Location:index.php');exit;}?><h2>Add User</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><div class="col-md-6"><label>Name</label><input name="name" class="form-control" required></div><div class="col-md-6"><label>Email</label><input name="email" type="email" class="form-control" required></div><div class="col-md-6"><label>Password</label><input name="password" type="password" class="form-control" required></div><div class="col-md-6"><label>Role</label><select name="role" class="form-select"><option>receptionist</option><option>doctor</option><option>admin</option></select></div></div><button class="btn btn-primary mt-3">Create User</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>